import pdfplumber
import pandas as pd
import json
from difflib import SequenceMatcher

# Load vendors and POs
vendors_df = pd.read_excel('/root/vendors.xlsx')
po_df = pd.read_csv('/root/purchase_orders.csv')

# Create lookup dictionaries
vendor_by_name = {row['name']: row for _, row in vendors_df.iterrows()}
vendor_by_id = {row['id']: row for _, row in vendors_df.iterrows()}
po_by_number = {row['po_number']: row for _, row in po_df.iterrows()}

# Function for fuzzy matching
def fuzzy_match_vendor(name, threshold=0.8):
    best_match = None
    best_ratio = 0
    for vendor_name in vendor_by_name.keys():
        ratio = SequenceMatcher(None, name.lower(), vendor_name.lower()).ratio()
        if ratio > best_ratio:
            best_ratio = ratio
            best_match = vendor_name
    if best_ratio >= threshold:
        return best_match
    return None

# Extract invoices from PDF
invoices = []
with pdfplumber.open('/root/invoices.pdf') as pdf:
    for page_num, page in enumerate(pdf.pages, 1):
        text = page.extract_text()
        lines = text.strip().split('\n')

        invoice = {'page': page_num}
        for line in lines:
            if line.startswith('From:'):
                invoice['vendor_name'] = line.replace('From:', '').strip()
            elif line.startswith('Total'):
                amount_str = line.replace('Total', '').replace('$', '').strip()
                invoice['amount'] = float(amount_str)
            elif line.startswith('Payment IBAN:'):
                invoice['iban'] = line.replace('Payment IBAN:', '').strip()
            elif line.startswith('PO Number:'):
                invoice['po_number'] = line.replace('PO Number:', '').strip()

        invoices.append(invoice)

print(f"Extracted {len(invoices)} invoices")
print("First 3 invoices:")
for inv in invoices[:3]:
    print(inv)
EOF
